#!/bin/bash
# **A8 で 10/31 に申請して審査中だった 202 件と、金融で申請した 7 件（t514）が、いま「審査中」「提携中」のどちらかを数える（t526）。** LLM 不使用・**$0**。読むだけで、申請は押さない。
# 予約「A8 審査中 202 件の確認」（2026-10-31 に利用者がダイアログで「11/1 に審査中…を確かめる」を選んだ）。
# t431〜t471 の画面には「失敗」「処理中」「申請欄が無い」が混ざり、画面だけでは結果が言えないため、一覧から確かめる。
# 再認証の画面は asp-probe.mjs の a8Reauth が Keychain で通す。
set -uo pipefail
RDIR="${OPS_REPORT_DIR:-/tmp}"
OUT="$RDIR/t526-a8-apply.md"
REPO="${DAILY_HACK_REPO:-${BLOG_REPO:-$HOME/projects/anta-baka-x/blog}}"
mkdir -p "$RDIR"
{ echo "# A8 の申請した案件の状態（t526・**\$0**）"; echo ""; echo "生成: **$(date '+%Y-%m-%dT%H:%M:%S%z')**"; echo ""; } > "$OUT"
NODE_BIN=/opt/homebrew/bin/node; [ -x "$NODE_BIN" ] || NODE_BIN="$(command -v node || true)"
[ -n "$NODE_BIN" ] || { echo "⚠️ node が無い" >> "$OUT"; cat "$OUT"; exit 0; }
git -C "$REPO" fetch -q origin main 2>/dev/null || true
run_limited() {
  local lim="$1"; shift
  "$@" &
  local pid=$! t0; t0=$(date +%s)
  while kill -0 "$pid" 2>/dev/null; do
    [ $(( $(date +%s) - t0 )) -ge "$lim" ] && { kill "$pid" 2>/dev/null; return 124; }
    sleep 2
  done
  wait "$pid" 2>/dev/null
}
